function reducer(state, action) {
  switch (action.type) {
    case 'submit':
      return { ...state, status: 'saving', error: null };
    case 'success':
      return { ...state, status: 'done', data: action.payload };
    case 'failure':
      return { ...state, status: 'idle', error: action.error };
    default:
      return state;
  }
}

